from hypothesis import given, strategies as st
import pytest


def flatten_iter(iterable):
    """``flatten_iter()`` yields all the elements from *iterable* while
    collapsing any nested iterables.

    >>> nested = [[1, 2], [[3], [4, 5]]]
    >>> list(flatten_iter(nested))
    [1, 2, 3, 4, 5]
    """
    from collections.abc import Iterable
    for item in iterable:
        if isinstance(item, Iterable) and (not isinstance(item, (str, bytes))):
            yield from flatten_iter(item)
        else:
            yield item


@given(iterable=st.recursive(st.integers() | st.text() | st.floats(allow_nan=False) | st.booleans() | st.none(), lambda children: st.lists(children, max_size=5) | st.tuples(children, children), max_leaves=20))
def test_idempotence(iterable):
    once = list(flatten_iter(iterable))
    twice = list(flatten_iter(once))
    assert twice == once


@given(iterable=st.recursive(st.integers() | st.text() | st.floats(allow_nan=False) | st.booleans() | st.none(), lambda children: st.lists(children, max_size=5) | st.tuples(children, children), max_leaves=20))
def test_invariant_preservation(iterable):
    from collections.abc import Iterable as IterableABC

    def manual_flatten(x):
        result = []
        for item in x:
            if isinstance(item, IterableABC) and not isinstance(item, (str, bytes)):
                result.extend(manual_flatten(item))
            else:
                result.append(item)
        return result

    expected = manual_flatten(iterable)
    actual = list(flatten_iter(iterable))

    def sort_key(v):
        return (str(type(v)), repr(v))

    assert sorted(actual, key=sort_key) == sorted(expected, key=sort_key)


@given(a=st.recursive(st.integers() | st.text() | st.floats(allow_nan=False) | st.booleans() | st.none(), lambda children: st.lists(children, max_size=5) | st.tuples(children, children), max_leaves=20), b=st.recursive(st.integers() | st.text() | st.floats(allow_nan=False) | st.booleans() | st.none(), lambda children: st.lists(children, max_size=5) | st.tuples(children, children), max_leaves=20))
def test_metamorphic(a, b):
    combined = list(flatten_iter([a, b]))
    separate = list(flatten_iter([a])) + list(flatten_iter([b]))
    assert combined == separate


@given(iterable=st.recursive(st.integers() | st.text() | st.floats(allow_nan=False) | st.booleans() | st.none(), lambda children: st.lists(children, max_size=5) | st.tuples(children, children), max_leaves=20))
def test_type_postcondition(iterable):
    result = flatten_iter(iterable)
    assert hasattr(result, '__iter__')
    assert hasattr(result, '__next__')


@given(iterable=st.recursive(st.integers() | st.text() | st.floats(allow_nan=False) | st.booleans() | st.none(), lambda children: st.lists(children, max_size=5) | st.tuples(children, children), max_leaves=20))
def test_totality(iterable):
    list(flatten_iter(iterable))

from hypothesis import given, strategies as st
import pytest


def under2camel(under_string):
    """Converts an underscored string to camelcased. Useful for turning a
    function name into a class name.

    >>> under2camel('complex_tokenizer')
    'ComplexTokenizer'
    """
    return ''.join((w.capitalize() or '_' for w in under_string.split('_')))


@given(under_string=st.one_of(st.text(alphabet=st.characters(whitelist_categories=('Ll','Lu','Nd'), whitelist_characters='_'), min_size=0, max_size=30), st.text()))
def test_type_postcondition(under_string):
    assert isinstance(under2camel(under_string), str)


@given(under_string=st.one_of(st.text(alphabet=st.characters(whitelist_categories=('Ll','Lu','Nd'), whitelist_characters='_'), min_size=0, max_size=30), st.text()))
def test_idempotence(under_string):
    assert under2camel(under2camel(under_string)) == under2camel(under_string)


@given(under_string=st.one_of(st.text(alphabet=st.characters(whitelist_categories=('Ll','Lu','Nd'), whitelist_characters='_'), min_size=0, max_size=30), st.text()))
def test_value_postcondition(under_string):
    result = under2camel(under_string)
    assert result == '' or result[0].isupper()


@given(under_string=st.one_of(st.text(alphabet=st.characters(whitelist_categories=('Ll','Lu','Nd'), whitelist_characters='_'), min_size=0, max_size=30), st.text()))
def test_totality(under_string):
    under2camel(under_string)

from hypothesis import given, strategies as st
import pytest


def camelize(string: str, uppercase_first_letter: bool=True) -> str:
    """
    Convert strings to CamelCase.

    Examples::

        >>> camelize("device_type")
        'DeviceType'
        >>> camelize("device_type", False)
        'deviceType'

    :func:`camelize` can be thought of as a inverse of :func:`underscore`,
    although there are some cases where that does not hold::

        >>> camelize(underscore("IOError"))
        'IoError'

    :param uppercase_first_letter: if set to `True` :func:`camelize` converts
        strings to UpperCamelCase. If set to `False` :func:`camelize` produces
        lowerCamelCase. Defaults to `True`.
    """
    import re
    if uppercase_first_letter:
        return re.sub('(?:^|_)(.)', lambda m: m.group(1).upper(), string)
    else:
        return string[0].lower() + camelize(string)[1:]


@given(string=st.text(alphabet=st.characters(whitelist_categories=('Ll','Lu','Nd')) | st.just('_'), min_size=1))
def test_idempotence(string):
    assert camelize(camelize(string)) == camelize(string)


@given(string=st.text(alphabet=st.characters(whitelist_categories=('Ll','Lu','Nd')) | st.just('_'), min_size=1), uppercase_first_letter=st.booleans())
def test_type_postcondition(string, uppercase_first_letter):
    assert isinstance(camelize(string, uppercase_first_letter), str)


@given(string=st.text(alphabet=st.characters(whitelist_categories=('Ll','Lu','Nd')) | st.just('_'), min_size=1))
def test_metamorphic(string):
    upper_result = camelize(string, True)
    lower_result = camelize(string, False)
    if upper_result:
        assert upper_result[0].isupper() or not upper_result[0].isalpha()
    if lower_result:
        assert lower_result[0].islower() or not lower_result[0].isalpha()


@given(string=st.text(alphabet=st.characters(whitelist_categories=('Ll','Lu','Nd')) | st.just('_'), min_size=1))
def test_totality(string):
    camelize(string)

