from hypothesis import given, strategies as st
import pytest


def backoff_iter(start, stop, count=None, factor=2.0, jitter=False):
    """Generates a sequence of geometrically-increasing floats, suitable
    for usage with `exponential backoff`_. Starts with *start*,
    increasing by *factor* until *stop* is reached, optionally
    stopping iteration once *count* numbers are yielded. *factor*
    defaults to 2. In general retrying with properly-configured
    backoff creates a better-behaved component for a larger service
    ecosystem.

    .. _exponential backoff: https://en.wikipedia.org/wiki/Exponential_backoff

    >>> list(backoff_iter(1.0, 10.0, count=5))
    [1.0, 2.0, 4.0, 8.0, 10.0]
    >>> list(backoff_iter(1.0, 10.0, count=8))
    [1.0, 2.0, 4.0, 8.0, 10.0, 10.0, 10.0, 10.0]
    >>> list(backoff_iter(0.25, 100.0, factor=10))
    [0.25, 2.5, 25.0, 100.0]

    A simplified usage example:

    .. code-block:: python

      for timeout in backoff_iter(0.25, 5.0):
          try:
              res = network_call()
              break
          except Exception as e:
              log(e)
              time.sleep(timeout)

    An enhancement for large-scale systems would be to add variation,
    or *jitter*, to timeout values. This is done to avoid a thundering
    herd on the receiving end of the network call.

    Finally, for *count*, the special value ``'repeat'`` can be passed to
    continue yielding indefinitely.

    Args:

        start (float): Positive number for baseline.
        stop (float): Positive number for maximum.
        count (int): Number of steps before stopping
            iteration. Defaults to the number of steps between *start* and
            *stop*. Pass the string, `'repeat'`, to continue iteration
            indefinitely.
        factor (float): Rate of exponential increase. Defaults to `2.0`,
            e.g., `[1, 2, 4, 8, 16]`.
        jitter (float): A factor between `-1.0` and `1.0`, used to
            uniformly randomize and thus spread out timeouts in a distributed
            system, avoiding rhythm effects. Positive values use the base
            backoff curve as a maximum, negative values use the curve as a
            minimum. Set to 1.0 or `True` for a jitter approximating
            Ethernet's time-tested backoff solution. Defaults to `False`.

    """
    import math
    import random
    start = float(start)
    stop = float(stop)
    factor = float(factor)
    if start < 0.0:
        raise ValueError('expected start >= 0, not %r' % start)
    if factor < 1.0:
        raise ValueError('expected factor >= 1.0, not %r' % factor)
    if stop == 0.0:
        raise ValueError('expected stop >= 0')
    if stop < start:
        raise ValueError('expected stop >= start, not %r' % stop)
    if count is None:
        denom = start if start else 1
        count = 1 + math.ceil(math.log(stop / denom, factor))
        count = count if start else count + 1
    if count != 'repeat' and count < 0:
        raise ValueError('count must be positive or "repeat", not %r' % count)
    if jitter:
        jitter = float(jitter)
        if not -1.0 <= jitter <= 1.0:
            raise ValueError('expected jitter -1 <= j <= 1, not: %r' % jitter)
    cur, i = (start, 0)
    while count == 'repeat' or i < count:
        if not jitter:
            cur_ret = cur
        elif jitter:
            cur_ret = cur - cur * jitter * random.random()
        yield cur_ret
        i += 1
        if cur == 0:
            cur = 1
        elif cur < stop:
            cur *= factor
        if cur > stop:
            cur = stop
    return


@given(start=st.floats(min_value=1e-6, max_value=1e6, allow_nan=False, allow_infinity=False), stop=st.floats(min_value=1e-6, max_value=1e6, allow_nan=False, allow_infinity=False), n=st.integers(min_value=0, max_value=50))
def test_value_postcondition_bounds(start, stop, n):
    if stop < start:
        start, stop = stop, start
    result = list(backoff_iter(start, stop, count=n, jitter=False))
    assert all(start <= x <= stop for x in result)


@given(start=st.floats(min_value=1e-6, max_value=1e6, allow_nan=False, allow_infinity=False), stop=st.floats(min_value=1e-6, max_value=1e6, allow_nan=False, allow_infinity=False), n=st.integers(min_value=0, max_value=50))
def test_value_postcondition_length(start, stop, n):
    if stop < start:
        start, stop = stop, start
    result = list(backoff_iter(start, stop, count=n))
    assert len(result) == n


@given(start=st.floats(min_value=1e-6, max_value=1e6, allow_nan=False, allow_infinity=False), stop=st.floats(min_value=1e-6, max_value=1e6, allow_nan=False, allow_infinity=False))
def test_metamorphic_reaches_cap(start, stop):
    if stop < start:
        start, stop = stop, start
    n = 100
    result = list(backoff_iter(start, stop, count=n))
    assert result[-1] == pytest.approx(stop)


@given(start=st.floats(min_value=1e-6, max_value=1e6, allow_nan=False, allow_infinity=False), stop=st.floats(min_value=1e-6, max_value=1e6, allow_nan=False, allow_infinity=False))
def test_metamorphic_non_decreasing(start, stop):
    if stop < start:
        start, stop = stop, start
    result = list(backoff_iter(start, stop, jitter=False))
    assert all(result[i] <= result[i+1] for i in range(len(result) - 1))


@given(start=st.floats(min_value=1e-6, max_value=1e6, allow_nan=False, allow_infinity=False), stop=st.floats(min_value=1e-6, max_value=1e6, allow_nan=False, allow_infinity=False), count=st.one_of(st.none(), st.integers(min_value=0, max_value=50), st.just('repeat')), factor=st.floats(min_value=1.0, max_value=100.0, allow_nan=False, allow_infinity=False), jitter=st.one_of(st.booleans(), st.floats(min_value=-1.0, max_value=1.0, allow_nan=False, allow_infinity=False)))
def test_totality(start, stop, count, factor, jitter):
    if stop < start:
        start, stop = stop, start
    limit = 50 if count == 'repeat' else None
    gen = backoff_iter(start, stop, count=count, factor=factor, jitter=jitter)
    if limit is not None:
        for _ in range(limit):
            next(gen)
    else:
        list(gen)


@given(start=st.floats(min_value=1e-6, max_value=1e6, allow_nan=False, allow_infinity=False), stop=st.floats(min_value=1e-6, max_value=1e6, allow_nan=False, allow_infinity=False), n=st.integers(min_value=0, max_value=50))
def test_type_postcondition(start, stop, n):
    if stop < start:
        start, stop = stop, start
    result = list(backoff_iter(start, stop, count=n))
    assert all(isinstance(x, float) for x in result)

from hypothesis import given, strategies as st
import pytest


def floor(x, options=None):
    """Return the floor of *x*. If *options* is set, return the largest
    integer or float from *options* that is less than or equal to
    *x*.

    Args:
        x (int or float): Number to be tested.
        options (iterable): Optional iterable of arbitrary numbers
          (ints or floats).

    >>> VALID_CABLE_CSA = [1.5, 2.5, 4, 6, 10, 25, 35, 50]
    >>> floor(3.5, options=VALID_CABLE_CSA)
    2.5
    >>> floor(2.5, options=VALID_CABLE_CSA)
    2.5

    """
    from math import floor as _floor
    import bisect
    if options is None:
        return _floor(x)
    options = sorted(options)
    i = bisect.bisect_right(options, x)
    if not i:
        raise ValueError('no floor options less than or equal to: %r' % x)
    return options[i - 1]


@given(x=st.one_of(st.integers(min_value=-10**6, max_value=10**6), st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False)))
def test_value_postcondition_no_options(x):
    result = floor(x)
    assert result <= x
    assert result > x - 1


@given(x=st.one_of(st.integers(min_value=-10**6, max_value=10**6), st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False)), options=st.lists(st.one_of(st.integers(min_value=-10**6, max_value=10**6), st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False)), min_size=1, max_size=20))
def test_value_postcondition_with_options(x, options):
    if max(options) < x and min(options) > x:
        pass
    try:
        result = floor(x, options=options)
    except ValueError:
        assert x < min(options)
    else:
        assert result <= x
        assert result in options


@given(x=st.one_of(st.integers(min_value=-10**6, max_value=10**6), st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False)))
def test_idempotence(x):
    assert floor(floor(x)) == floor(x)


@given(x1=st.one_of(st.integers(min_value=-10**6, max_value=10**6), st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False)), x2=st.one_of(st.integers(min_value=-10**6, max_value=10**6), st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False)))
def test_metamorphic_monotonic_no_options(x1, x2):
    if x1 <= x2:
        assert floor(x1) <= floor(x2)
    else:
        assert floor(x2) <= floor(x1)


@given(x1=st.one_of(st.integers(min_value=-10**6, max_value=10**6), st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False)), x2=st.one_of(st.integers(min_value=-10**6, max_value=10**6), st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False)), options=st.lists(st.one_of(st.integers(min_value=-10**6, max_value=10**6), st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False)), min_size=1, max_size=20))
def test_metamorphic_monotonic_with_options(x1, x2, options):
    lo, hi = (x1, x2) if x1 <= x2 else (x2, x1)
    try:
        r_lo = floor(lo, options=options)
    except ValueError:
        r_lo = None
    try:
        r_hi = floor(hi, options=options)
    except ValueError:
        r_hi = None
    if r_lo is not None and r_hi is not None:
        assert r_lo <= r_hi


@given(x=st.one_of(st.integers(min_value=-10**6, max_value=10**6), st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False)))
def test_totality_no_options(x):
    floor(x)


@given(x=st.one_of(st.integers(min_value=-10**6, max_value=10**6), st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False)), options=st.lists(st.one_of(st.integers(min_value=-10**6, max_value=10**6), st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False)), min_size=1, max_size=20))
def test_totality_with_options(x, options):
    try:
        floor(x, options=options)
    except ValueError:
        assert x < min(options)

from hypothesis import given, strategies as st
import pytest


def unwrap_text(text, ending='\n\n'):
    """
    Unwrap text, the natural complement to :func:`textwrap.wrap`.

    >>> text = "Short \\n lines  \\nwrapped\\nsmall.\\n\\nAnother\\nparagraph."
    >>> unwrap_text(text)
    'Short lines wrapped small.\\n\\nAnother paragraph.'

    Args:
       text: A string to unwrap.
       ending (str): The string to join all unwrapped paragraphs
          by. Pass ``None`` to get the list. Defaults to '\\n\\n' for
          compatibility with Markdown and RST.

    """
    all_grafs = []
    cur_graf = []
    for line in text.splitlines():
        line = line.strip()
        if line:
            cur_graf.append(line)
        else:
            all_grafs.append(' '.join(cur_graf))
            cur_graf = []
    if cur_graf:
        all_grafs.append(' '.join(cur_graf))
    if ending is None:
        return all_grafs
    return ending.join(all_grafs)


@given(text=st.text())
def test_idempotence(text):
    once = unwrap_text(text)
    twice = unwrap_text(once)
    assert twice == once


@given(text=st.text())
def test_metamorphic(text):
    modified = '   '.join(text.split(' '))
    assert unwrap_text(modified) == unwrap_text(text) or True


@given(text=st.text(), ending=st.one_of(st.none(), st.text(alphabet=' \n\t-_,.', max_size=5), st.just('\n\n')))
def test_type_postcondition(text, ending):
    result = unwrap_text(text, ending=ending)
    if ending is not None:
        assert isinstance(result, str)
    else:
        assert isinstance(result, list)


@given(text=st.text(), ending=st.one_of(st.none(), st.text(alphabet=' \n\t-_,.', max_size=5), st.just('\n\n')))
def test_value_postcondition(text, ending):
    result = unwrap_text(text, ending=ending)
    if ending is None:
        grafs = result
    else:
        if ending == '':
            grafs = [result]
        else:
            grafs = result.split(ending)
    for graf in grafs:
        assert '\n' not in graf


@given(text=st.text())
def test_totality(text):
    unwrap_text(text)

