from hypothesis import given, strategies as st
import pytest


def to_text(obj, maxlen=None):
    try:
        text = str(obj)
    except Exception:
        try:
            text = str(repr(obj))
        except Exception:
            text = str(object.__repr__(obj))
    if maxlen and len(text) > maxlen:
        text = text[:maxlen - 3] + '...'
    return text


@given(obj=st.one_of(st.none(), st.booleans(), st.integers(), st.floats(), st.text(), st.binary(), st.lists(st.integers(), max_size=5), st.dictionaries(st.text(), st.integers(), max_size=5), st.tuples(st.integers(), st.text())), maxlen=st.one_of(st.none(), st.integers(min_value=0, max_value=1000)))
def test_type_postcondition(obj, maxlen):
    assert isinstance(to_text(obj, maxlen), str)


@given(obj=st.one_of(st.none(), st.booleans(), st.integers(), st.floats(), st.text(), st.binary(), st.lists(st.integers(), max_size=5), st.dictionaries(st.text(), st.integers(), max_size=5), st.tuples(st.integers(), st.text())), maxlen=st.one_of(st.none(), st.integers(min_value=0, max_value=1000)))
def test_value_postcondition(obj, maxlen):
