    first = subdict(d, keep=keep, drop=drop)
    second = subdict(first, keep=keep, drop=drop)
    assert second == first


@given(d=st.dictionaries(st.text(), st.integers()), drop_keys=st.lists(st.text()))
def test_metamorphic(d, drop_keys):
    left = subdict(d, drop=drop_keys)
    right = subdict(d, keep=set(d.keys()) - set(drop_keys))
