def xfrange(stop, start=None, step=1.0):
    """Same as :func:`frange`, but generator-based instead of returning a
    list.

    >>> tuple(xfrange(1, 3, step=0.75))
    (1.0, 1.75, 2.5)

    See :func:`frange` for more details.
    """
    if not step:
        raise ValueError('step must be non-zero')
    if start is None:
        start, stop = (0.0, stop * 1.0)
    else:
        stop, start = (start * 1.0, stop * 1.0)
    cur = start
    while cur < stop:
        yield cur
        cur += step


@given(stop=st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False), start=st.one_of(st.none(), st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False)), step=st.floats(min_value=0.01, max_value=1000, allow_nan=False, allow_infinity=False).map(lambda x: x if x != 0 else 0.01) | st.floats(min_value=-1000, max_value=-0.01, allow_nan=False, allow_infinity=False))
def test_value_postcondition(stop, start, step):
    if step <= 0:
        return
    result = list(xfrange(stop, start, step))
    real_start = 0.0 if start is None else start * 1.0
    real_stop = stop * 1.0 if start is None else start * 1.0
    real_stop = stop * 1.0 if start is None else stop * 1.0
    real_start2, real_stop2 = (0.0, stop * 1.0) if start is None else (start * 1.0, stop * 1.0)
    assert all(real_start2 <= x < real_stop2 for x in result)


@given(stop=st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False), start=st.one_of(st.none(), st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False)), step=st.floats(min_value=0.01, max_value=1000, allow_nan=False, allow_infinity=False).map(lambda x: x if x != 0 else 0.01) | st.floats(min_value=-1000, max_value=-0.01, allow_nan=False, allow_infinity=False))
def test_invariant_preservation(stop, start, step):
    result = list(xfrange(stop, start, step))
    if step > 0:
        assert all(result[i] < result[i+1] for i in range(len(result)-1))
    else:
        assert all(result[i] > result[i+1] for i in range(len(result)-1))


@given(stop=st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False), start=st.one_of(st.none(), st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False)), step=st.floats(min_value=0.01, max_value=1000, allow_nan=False, allow_infinity=False).map(lambda x: x if x != 0 else 0.01) | st.floats(min_value=-1000, max_value=-0.01, allow_nan=False, allow_infinity=False), k=st.floats(min_value=0.1, max_value=10, allow_nan=False, allow_infinity=False))
def test_metamorphic(stop, start, step, k):
    len1 = len(list(xfrange(stop, start, step)))
    scaled_start = None if start is None else start * k
    len2 = len(list(xfrange(stop * k, scaled_start, step * k)))
    assert abs(len1 - len2) <= 1


@given(stop=st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False), start=st.one_of(st.none(), st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False)), step=st.floats(min_value=0.01, max_value=1000, allow_nan=False, allow_infinity=False).map(lambda x: x if x != 0 else 0.01) | st.floats(min_value=-1000, max_value=-0.01, allow_nan=False, allow_infinity=False))
