    result = list(xfrange(stop, start, step))
    assert all(isinstance(x, float) for x in result)

from hypothesis import given, strategies as st
import pytest


def ceil(x, options=None):
    """Return the ceiling of *x*. If *options* is set, return the smallest
    integer or float from *options* that is greater than or equal to
    *x*.

    Args:
        x (int or float): Number to be tested.
        options (iterable): Optional iterable of arbitrary numbers
          (ints or floats).

    >>> VALID_CABLE_CSA = [1.5, 2.5, 4, 6, 10, 25, 35, 50]
    >>> ceil(3.5, options=VALID_CABLE_CSA)
    4
    >>> ceil(4, options=VALID_CABLE_CSA)
    4
    """
    from math import ceil as _ceil
    import bisect
    if options is None:
        return _ceil(x)
    options = sorted(options)
    i = bisect.bisect_left(options, x)
    if i == len(options):
        raise ValueError('no ceil options greater than or equal to: %r' % x)
    return options[i]


@given(x=st.one_of(st.integers(min_value=-10**9, max_value=10**9), st.floats(allow_nan=False, allow_infinity=False, min_value=-1e9, max_value=1e9)))
def test_value_postcondition(x):
    assert ceil(x) >= x


@given(x=st.one_of(st.integers(min_value=-10**6, max_value=10**6), st.floats(allow_nan=False, allow_infinity=False, min_value=-1e6, max_value=1e6)), options=st.lists(st.one_of(st.integers(min_value=-10**6, max_value=10**6), st.floats(allow_nan=False, allow_infinity=False, min_value=-1e6, max_value=1e6)), min_size=1, max_size=20))
def test_value_postcondition_2(x, options):
    if max(options) < x:
        return
    result = ceil(x, options)
    assert result >= x
    assert result in options


@given(x=st.one_of(st.integers(min_value=-10**9, max_value=10**9), st.floats(allow_nan=False, allow_infinity=False, min_value=-1e9, max_value=1e9)))
def test_idempotence(x):
    assert ceil(ceil(x)) == ceil(x)


@given(x1=st.one_of(st.integers(min_value=-10**9, max_value=10**9), st.floats(allow_nan=False, allow_infinity=False, min_value=-1e9, max_value=1e9)), x2=st.one_of(st.integers(min_value=-10**9, max_value=10**9), st.floats(allow_nan=False, allow_infinity=False, min_value=-1e9, max_value=1e9)))
def test_metamorphic(x1, x2):
    if x1 <= x2:
        assert ceil(x1) <= ceil(x2)


@given(x=st.one_of(st.integers(min_value=-10**9, max_value=10**9), st.floats(allow_nan=False, allow_infinity=False, min_value=-1e9, max_value=1e9)))
