    ceil(x)

from hypothesis import given, strategies as st
import pytest


def clamp(x, lower=float('-inf'), upper=float('inf')):
    """Limit a value to a given range.

    Args:
        x (int or float): Number to be clamped.
        lower (int or float): Minimum value for x.
        upper (int or float): Maximum value for x.

    The returned value is guaranteed to be between *lower* and
    *upper*. Integers, floats, and other comparable types can be
    mixed.

    >>> clamp(1.0, 0, 5)
    1.0
    >>> clamp(-1.0, 0, 5)
    0
    >>> clamp(101.0, 0, 5)
    5
    >>> clamp(123, upper=5)
    5

    Similar to `numpy's clip`_ function.

    .. _numpy's clip: http://docs.scipy.org/doc/numpy/reference/generated/numpy.clip.html

    """
    if upper < lower:
        raise ValueError('expected upper bound (%r) >= lower bound (%r)' % (upper, lower))
    return min(max(x, lower), upper)


@given(x=st.one_of(st.integers(), st.floats(allow_nan=False)), lower=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=True)), upper=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=True)))
def test_value_postcondition(x, lower, upper):
    if lower <= upper:
        result = clamp(x, lower, upper)
        assert lower <= result <= upper


@given(x=st.one_of(st.integers(), st.floats(allow_nan=False)), lower=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=True)), upper=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=True)))
def test_idempotence(x, lower, upper):
    if lower <= upper:
        once = clamp(x, lower, upper)
        twice = clamp(once, lower, upper)
        assert twice == once


@given(x1=st.one_of(st.integers(), st.floats(allow_nan=False)), x2=st.one_of(st.integers(), st.floats(allow_nan=False)), lower=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=True)), upper=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=True)))
def test_metamorphic(x1, x2, lower, upper):
    if lower <= upper and x1 <= x2:
        assert clamp(x1, lower, upper) <= clamp(x2, lower, upper)


@given(x=st.one_of(st.integers(), st.floats(allow_nan=False)), lower=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=True)), upper=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=True)))
def test_value_postcondition_identity(x, lower, upper):
    if lower <= upper and lower <= x <= upper:
        assert clamp(x, lower, upper) == x


@given(x=st.one_of(st.integers(), st.floats(allow_nan=False)), lower=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=True)), upper=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=True)))
def test_totality(x, lower, upper):
    if lower <= upper:
        clamp(x, lower, upper)

